<section class="panel"><h2>Datos de la cuenta</h2><form method="post" class="form-grid"><label>Total de la cuenta (COP)<input type="number" name="total" min="0" step="0.01" required></label><label>Porcentaje de propina<select name="percent"><option value="5">5%</option><option value="10" selected>10%</option><option value="15">15%</option><option value="20">20%</option></select></label><label>Número de personas<input type="number" name="people" min="1" value="1" required></label><button class="btn" name="calculate" value="1">Calcular propina</button></form></section><?php if($result): ?><section class="panel result"><h2>Resultado</h2><div class="stats"><div><small>Propina</small><strong>$<?=number_format($result['tip'],2,',','.')?></strong></div><div><small>Total con propina</small><strong>$<?=number_format($result['grand'],2,',','.')?></strong></div><div><small>Valor por persona</small><strong>$<?=number_format($result['each'],2,',','.')?></strong></div></div><p>Propina del <?=$result['percent']?>% dividida entre <?=$result['people']?> persona(s).</p></section><?php endif ?>
